using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace NightLens {
static class EquipmentTests {
 static T Field<T>(EquipmentForm form,string name) where T:class{return typeof(EquipmentForm).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form) as T;}
 static void Snapshot(Form form,string path){form.Show();Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
 public static void Run(Forecast f,DateTime now,string[] args,List<string> log){Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);log.Add("PASS: "+message);};var all=EquipmentLibrary.All;check(EquipmentLibrary.Error==""&&all.Count==100,"100 distinct device profiles load from the packaged library");check(all.Count(p=>!p.Smart)==91&&all.Count(p=>p.Smart)==9,"91 camera entries and nine smart-telescope optical profiles available");check(all.All(p=>!string.IsNullOrWhiteSpace(p.Source)&&!string.IsNullOrWhiteSpace(p.VerifiedOn)&&!string.IsNullOrWhiteSpace(p.GainGuidance)),"Every profile has a source, review date and gain guidance");check(all.Count(p=>p.GainStart.HasValue)==30,"Numeric gain only provided for 30 documented entries");
 var settings=new Settings{WindowsLocation=false};var night=new Night(settings,f,now);var pick=new Pick{Target=new Target("Test galaxy","Galaxy",1,30,30,20){Canonical="Test galaxy",Magnitude=9},Fit="Fits one frame",Alt=70,Start=night.Dark.First(),End=night.Dark.Last()};
 foreach(var p in all.Where(p=>p.Smart)){var rig=new Rig();EquipmentLibrary.Apply(rig,p);rig.GainOverride=500;check(EquipmentLibrary.Gain(rig).Contains("not adjustable"),p.Id+" never suggests adjustable gain");if(p.HasSensor){var plan=CapturePlanning.For(pick,rig,settings,night);check(plan.SubSeconds.HasValue&&EquipmentLibrary.Subs(rig).Contains(plan.SubSeconds.Value)&&(!p.MaxSub.HasValue||plan.SubSeconds<=p.MaxSub),p.Id+" exposure stays within confirmed choices and model maximum");}}
 var camera=new Rig{Focal=408,Aperture=60,Mount="Equatorial / tracker"};EquipmentLibrary.Apply(camera,all.Single(p=>p.Id=="ASI2600MC Air"));check(!EquipmentLibrary.Smart(camera)&&!EquipmentLibrary.Gain(camera).Contains("not adjustable"),"ASI Air is an adjustable camera, not a fixed-gain smart telescope");camera.GainOverride=137;check(CapturePlanning.For(pick,camera,settings,night).Gain.StartsWith("137"),"Camera gain override reaches the capture plan");var restored=Json.Read<Rig>(Json.Write(camera));check(restored.GainOverride==137&&restored.DeviceProfileId==camera.DeviceProfileId,"Device identity and gain override persist through settings serialization");EquipmentLibrary.Apply(camera,all.Single(p=>p.Id=="ASI2600MC Pro"));check(camera.GainOverride==null&&Math.Abs(camera.SensorW-23.49248)<.001&&camera.Width>3,"Selecting a new camera resets old gain override and updates framing dimensions");check(EquipmentLibrary.Find(settings.Rigs[1]).Id=="ASI585MC Pro"&&EquipmentLibrary.Gain(settings.Rigs[1],true)=="200","Existing ASI585MC Pro setup maps to the model library without migration");check(all.Single(p=>p.Id=="ASI678MC").GainStart==182&&all.Single(p=>p.Id=="ASI678MM").GainStart==null,"Color-model numeric gain is not copied to an unverified mono variant");
 EquipmentLibrary.Apply(camera,all.Single(p=>p.Id=="ASI990MM Pro"));var swir=CapturePlanning.For(pick,camera,settings,night);check(swir.MinHours==null&&swir.SubSeconds==null&&swir.Integration.Contains("SWIR"),"SWIR cameras do not receive visible-light Bortle exposure estimates");
 string folder=Path.GetDirectoryName(args[3]);Style.SetTheme("Dark");using(var editor=new EquipmentForm(settings)){editor.Show();Application.DoEvents();check(Field<ComboBox>(editor,"camera").Items.Count==92&&Field<ComboBox>(editor,"telescope").Items.Cast<object>().Select(x=>x.ToString()).SequenceEqual(new[]{"Seestar S30 Pro","Seestar S30","Seestar S50","Seestar S50 Pro","Other"}),"Four Seestar models plus Other; generic camera selector includes Other");
 editor.SelectDevice("ASI2600MC Pro");check(editor.Commit()&&editor.Rigs[0].DeviceProfileId=="ASI2600MC Pro"&&Math.Abs(editor.Rigs[0].SensorW-23.49248)<.001,"Camera selector saves model specifications");check(Field<RadioButton>(editor,"customOption").Checked&&Field<NumericUpDown>(editor,"focal").Visible,"Custom setup exposes editable optics and sensor dimensions");Field<CheckBox>(editor,"overrideGain").Checked=true;Field<NumericUpDown>(editor,"gain").Value=123;check(editor.Commit()&&editor.Rigs[0].GainOverride==123,"Equipment editor saves custom camera gain");Snapshot(editor,Path.Combine(folder,"Camera library preview.png"));
 foreach(var field in new Control[]{Field<TextBox>(editor,"name"),Field<NumericUpDown>(editor,"focal"),Field<NumericUpDown>(editor,"aperture"),Field<NumericUpDown>(editor,"sw"),Field<NumericUpDown>(editor,"sh"),Field<ComboBox>(editor,"camera"),Field<ComboBox>(editor,"mount")}){check(field.Height>=field.PreferredSize.Height&&field.Bottom<=field.Parent.ClientSize.Height,"Input fits its preferred height and parent: "+field.GetType().Name);}
 editor.SelectDevice("Seestar S50 Pro — Tele");check(editor.Commit()&&editor.Rigs[0].GainOverride==null&&!Field<NumericUpDown>(editor,"gain").Visible&&!Field<NumericUpDown>(editor,"focal").Visible&&Field<RadioButton>(editor,"smartOption").Checked,"Smart telescope mode hides camera/gain editors and displays read-only optics");check(editor.Rigs[0].Name=="Seestar S50 Pro"&&Field<ComboBox>(editor,"telescope").Text=="Seestar S50 Pro","Smart telescope names do not expose lens or edition variants");Field<TextBox>(editor,"allowed").Text="10,30,60";check(editor.Commit()&&EquipmentLibrary.Subs(editor.Rigs[0]).Contains(60),"App-confirmed Pro exposure choices may reach documented 60 s maximum");Field<TextBox>(editor,"allowed").Text="10,90";check(!editor.Commit(),"Pro exposure beyond documented 60 s maximum is rejected");Field<TextBox>(editor,"allowed").Text="10";editor.Commit();Snapshot(editor,Path.Combine(folder,"Smart telescope library preview.png"));editor.SelectDevice("Seestar S50");Field<TextBox>(editor,"allowed").Text="60";check(!editor.Commit(),"Original S50 cannot inherit Pro 60 s exposure setting");Field<TextBox>(editor,"allowed").Text="15";check(!editor.Commit(),"Original S50 rejects unsupported intermediate exposure durations");editor.SelectOther(false);check(!editor.Commit(),"Other camera requires a model name and sensor dimensions");Field<TextBox>(editor,"otherName").Text="Canon EOS custom camera";Field<NumericUpDown>(editor,"sw").Value=22.3m;Field<NumericUpDown>(editor,"sh").Value=14.9m;check(editor.Commit()&&editor.Rigs[0].CustomDevice&&!EquipmentLibrary.Smart(editor.Rigs[0])&&editor.Rigs[0].Camera=="Canon EOS custom camera","Non-ZWO Other camera saves and remains a custom camera");Snapshot(editor,Path.Combine(folder,"Other camera preview.png"));editor.SelectOther(true);check(!editor.Commit()&&Field<Button>(editor,"otherSpecs").Visible&&!Field<NumericUpDown>(editor,"focal").Visible,"Other smart telescope requests separate specifications and keeps the main optics read-only");Field<TextBox>(editor,"otherName").Text="Other maker smart telescope";Field<NumericUpDown>(editor,"focal").Value=300;Field<NumericUpDown>(editor,"aperture").Value=50;Field<NumericUpDown>(editor,"sw").Value=8;Field<NumericUpDown>(editor,"sh").Value=6;Field<TextBox>(editor,"allowed").Text="5,10,20";check(editor.Commit()&&EquipmentLibrary.Smart(editor.Rigs[0])&&EquipmentLibrary.Gain(editor.Rigs[0]).Contains("not adjustable"),"Other smart telescope saves custom specifications with app-controlled gain");Snapshot(editor,Path.Combine(folder,"Other telescope preview.png"));check(settings.Rigs[0].DeviceProfileId==null&&settings.Rigs[0].Name=="Seestar S50","Editing and cancelling preserves existing saved setups");}
 var dual=new Rig{Name="Seestar S30 Pro"};EquipmentLibrary.Apply(dual,EquipmentLibrary.SmartProfile("Seestar S30 Pro","Tele"));EquipmentLibrary.NormalizeSmartRig(dual);double teleWidth=dual.Width;EquipmentLibrary.SelectLens(dual,"Wide");check(dual.SmartLens=="Wide"&&dual.Width>teleWidth*8&&dual.DeviceProfileId=="Seestar S30 Pro — Wide"&&dual.Name=="Seestar S30 Pro","Lens switching updates framing while retaining the setup's model name");var savedWide=Json.Read<Rig>(Json.Write(dual));EquipmentLibrary.NormalizeSmartRig(savedWide);check(savedWide.SmartLens=="Wide"&&savedWide.Focal==6,"Selected lens and optics persist across settings reload");var edition=new Rig();EquipmentLibrary.Apply(edition,all.Single(p=>p.Id=="Seestar S30 Pro Eclipse Edition — Wide"));EquipmentLibrary.NormalizeSmartRig(edition);check(edition.Name=="Seestar S30 Pro"&&edition.DeviceProfileId=="Seestar S30 Pro — Wide","Existing special-edition profile maps to the four-model selector");
 var originalS30=new Rig{Name="S30"};EquipmentLibrary.Apply(originalS30,EquipmentLibrary.SmartProfile("Seestar S30","Tele"));EquipmentLibrary.NormalizeSmartRig(originalS30);EquipmentLibrary.SelectLens(originalS30,"Wide");originalS30.SensorW=5;originalS30.SensorH=3;EquipmentLibrary.SelectLens(originalS30,"Tele");EquipmentLibrary.SelectLens(originalS30,"Wide");check(originalS30.SensorW==5&&originalS30.SensorH==3,"Manually confirmed original-S30 wide dimensions survive switching lenses");
 using(var main=new MainForm(true)){var state=(Settings)typeof(MainForm).GetField("s",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(main);state.Rigs=new List<Rig>{savedWide};state.Active=0;main.LoadTest(f,now);main.Show();Application.DoEvents();check(Descendants(main).Any(c=>c.AccessibleName=="Shooting lens"),"Multi-lens smart telescope displays the main-screen lens selector");Snapshot(main,Path.Combine(folder,"Lens selection preview.png"));var change=main.ChangeLens("Tele");while(!change.IsCompleted){Application.DoEvents();System.Threading.Thread.Sleep(5);}change.GetAwaiter().GetResult();check(state.Rigs[0].SmartLens=="Tele"&&state.Rigs[0].Focal==160,"Main-screen lens selection recalculates with the selected optics");state.Rigs=new Settings().Rigs;state.Active=0;main.PaintView();check(!Descendants(main).Any(c=>c.AccessibleName=="Shooting lens"),"Single-lens S50 hides the lens selector");state.Active=1;main.PaintView();check(!Descendants(main).Any(c=>c.AccessibleName=="Shooting lens"),"Custom equipment hides the smart-telescope lens selector");}
 var entered=new Rig();using(var specs=new OpticalSpecsForm(entered)){Snapshot(specs,Path.Combine(folder,"Other telescope specifications preview.png"));var values=Descendants(specs).OfType<NumericUpDown>().ToArray();foreach(var value in values)value.Value=20;Descendants(specs).OfType<Button>().Single(button=>button.Text=="Use specifications").PerformClick();check(specs.DialogResult==DialogResult.OK&&entered.Focal==20&&entered.Aperture==20&&entered.SensorW==20&&entered.SensorH==20,"Other telescope specification dialog returns validated values");}
 Style.SetTheme("Dark");
 }
 static IEnumerable<Control> Descendants(Control parent){foreach(Control child in parent.Controls){yield return child;foreach(var nested in Descendants(child))yield return nested;}}
}
}
